-- ============================================================================
-- DupDetect group segregation (Feature B): seed all 13 collection codes in
-- WORKFLOW_MASTER, each DUP_JSON.namespace.matchCollectionCodes = its group's full
-- code list. The engine scopes duplicate detection to candidates whose WORK_ITEM_BIN
-- COLLECTION_CODE is in this list, so items in different groups never match.
-- Governance reference: business_rules.COLLECTION_CODE_GROUP.
-- Run against: dup_detect (${DB_NAME_DUP_DETECT})
-- ============================================================================
USE ${DB_NAME_DUP_DETECT};

-- Id was a plain PK; make it auto-increment so multi-row seeds don't need explicit ids.
ALTER TABLE WORKFLOW_MASTER MODIFY COLUMN Id INT NOT NULL AUTO_INCREMENT;

ON DUPLICATE KEY UPDATE Name=VALUES(Name), DUP_JSON=VALUES(DUP_JSON);

SELECT 'dup WORKFLOW_MASTER matchCollectionCodes seeded' AS result;
